import{_ as i,A as d,o as t,c,O as s,b as g,w as o,Z as e,E as a,a as l}from"./chunks/framework.2c2d5a61.js";const J=JSON.parse('{"title":"JVM","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/02-JVM.md","filePath":"interview/后端/Java/02-JVM.md","lastUpdated":1789026500000}'),p={name:"interview/后端/Java/02-JVM.md"};function h(E,r,M,m,C,u){const n=d("Mermaid");return t(),c("div",null,[r[3]||(r[3]=s('<h1 id="jvm" tabindex="-1">JVM <a class="header-anchor" href="#jvm" aria-label="Permalink to &quot;JVM&quot;">​</a></h1><blockquote><p><strong>怎么用这份笔记</strong></p><ul><li>分级：<code>★★★ 必须吃透</code> / <code>★★☆ 了解即可（记结论就行）</code> / <code>★☆☆ 可以跳过（一句话看一眼）</code></li><li>【简历亮点，高频追问】：简历里写过的技术，面试官会顺着往下挖，这段必须能展开讲</li><li>每个考点固定三段：<strong>通俗理解 → 我的项目关联 → 面试答题话术</strong></li><li>「我的项目关联」里的坑分两种，别搞混： <ul><li>写**「线上」**= 真实发生过的问题，可以直接讲现象和修复</li><li>写**「通用坑」<strong>= 经典坑 / 资料里学到的，我们项目没实际踩到，面试时</strong>别说成自己踩过**</li></ul></li></ul></blockquote><hr><h2 id="_1-jvm-内存区域划分-哪些会-oom-★★★" tabindex="-1">1. JVM 内存区域划分，哪些会 OOM ★★★ <a class="header-anchor" href="#_1-jvm-内存区域划分-哪些会-oom-★★★" aria-label="Permalink to &quot;1. JVM 内存区域划分，哪些会 OOM ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> JVM 把内存分成几块：跟线程一对一的是**「线程私有」<strong>的——<strong>程序计数器</strong>（记执行到哪行，<strong>唯一不会 OOM</strong>）、<strong>虚拟机栈</strong>（方法调用的栈帧，递归太深会 <strong>StackOverflowError</strong>）、<strong>本地方法栈</strong>；所有线程共用的是</strong>「线程共享」<strong>的——<strong>堆</strong>（放对象，GC 主战场）、<strong>方法区 / 元空间</strong>（放类信息、静态变量、常量）。另外还有一块堆外的</strong>直接内存**。</p><p><strong>我的项目关联</strong> 网关、互联互通、对账这几个服务都跑在 Docker 容器里，容器内存有限，所以我最关心两件事：<strong>堆别撑爆</strong>（堆 OOM），<strong>元空间别无限涨</strong>（用 CGLIB 动态代理、频繁热部署会产生很多类）。我们启动参数里堆是 <code>-Xms</code>/<code>-Xmx</code> 设成相等，元空间也给了上限，就是防容器被拖垮。</p><p><strong>面试答题话术</strong> 「分<strong>线程私有</strong>和<strong>共享</strong>两类。私有的有<strong>程序计数器</strong>、<strong>虚拟机栈</strong>、<strong>本地方法栈</strong>；共享的是<strong>堆</strong>、<strong>方法区</strong>（8 之后叫<strong>元空间</strong>）。会 OOM 的是<strong>堆</strong>、<strong>元空间</strong>、<strong>直接内存</strong>，栈是 <strong>StackOverflowError</strong> 为主。放容器里跑的话，堆和元空间我都会显式给上限，不然元空间默认能吃满物理内存，把容器搞挂。」</p><hr><h2 id="_2-对象创建过程、内存布局、对象头-★★☆" tabindex="-1">2. 对象创建过程、内存布局、对象头 ★★☆ <a class="header-anchor" href="#_2-对象创建过程、内存布局、对象头-★★☆" aria-label="Permalink to &quot;2. 对象创建过程、内存布局、对象头 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><code>new</code> 一个对象大概五步：先检查类加载了没 → 在堆里分一块内存 → 内存清零（保证字段有默认值）→ 设对象头 → 执行构造器。对象在内存里分三块：<strong>对象头</strong>（<strong>Mark Word</strong> 存 hashCode、GC 年龄、锁状态，加类型指针）、<strong>实例数据</strong>（字段值）、<strong>对齐填充</strong>（凑成 8 字节整数倍）。分配内存有<strong>指针碰撞</strong>和<strong>空闲列表</strong>两种，还有 <strong>TLAB</strong> 让线程先在自己的小缓冲里分，减少竞争。</p>',10)),(t(),g(e,null,{default:o(()=>[a(n,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%E7%B1%BB%E5%8A%A0%E8%BD%BD%E6%A3%80%E6%9F%A5%5D%20--%3E%20B%5B%E5%88%86%E9%85%8D%E5%86%85%E5%AD%98%3Cbr%2F%3E%E6%8C%87%E9%92%88%E7%A2%B0%E6%92%9E%20%2F%20%E7%A9%BA%E9%97%B2%E5%88%97%E8%A1%A8%5D%0A%20%20%20%20B%20--%3E%20C%5B%E5%86%85%E5%AD%98%E6%B8%85%E9%9B%B6%3Cbr%2F%3E%E5%AD%97%E6%AE%B5%E7%BB%99%E9%BB%98%E8%AE%A4%E5%80%BC%5D%0A%20%20%20%20C%20--%3E%20D%5B%E8%AE%BE%E7%BD%AE%E5%AF%B9%E8%B1%A1%E5%A4%B4%3Cbr%2F%3EMark%20Word%20%2B%20%E7%B1%BB%E5%9E%8B%E6%8C%87%E9%92%88%5D%0A%20%20%20%20D%20--%3E%20E%5B%E6%89%A7%E8%A1%8C%E6%9E%84%E9%80%A0%E5%99%A8%3Cbr%2F%3E%E7%9C%9F%E6%AD%A3%E5%88%9D%E5%A7%8B%E5%8C%96%5D%0A"})]),fallback:o(()=>r[0]||(r[0]=[l(" Loading... ")])),_:1})),r[4]||(r[4]=s('<p><strong>我的项目关联</strong> 这块主要是为了回答「HashMap 里对象多大」「<strong>锁升级</strong>」这类延伸问题。实际开发我不直接碰<strong>对象头</strong>，但知道它跟锁升级（<strong>偏向锁</strong> → <strong>轻量级锁</strong> → <strong>重量级锁</strong>）是一回事，问 <strong>synchronized</strong> 的时候会用到。</p><p><strong>面试答题话术</strong> 「对象创建是：<strong>类加载检查</strong>、分内存、清零、设<strong>对象头</strong>、执行构造器。对象头里 <strong>Mark Word</strong> 是关键，<strong>hashCode</strong>、<strong>GC 年龄</strong>、<strong>锁状态</strong>都塞在里面，会复用同一块位。分内存有<strong>指针碰撞</strong>和<strong>空闲列表</strong>，HotSpot 用 <strong>TLAB</strong> 让线程本地分配减少<strong>锁竞争</strong>。TLAB 这个点被问到我就说：它是<strong>线程私有</strong>的一小块堆，线程先在自己这块分，分不下了再走 <strong>CAS</strong>。」</p><hr><h2 id="_3-如何判断对象是垃圾-四种引用-★★★" tabindex="-1">3. 如何判断对象是垃圾；四种引用 ★★★ <a class="header-anchor" href="#_3-如何判断对象是垃圾-四种引用-★★★" aria-label="Permalink to &quot;3. 如何判断对象是垃圾；四种引用 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 两种算法：<strong>引用计数</strong>（被引用数归零就回收，但解决不了 A 和 B 互相引用）和<strong>可达性分析</strong>（从 <strong>GC Roots</strong> 出发，能走到的就活着，走不到的才算垃圾）。HotSpot 用的是可达性分析。GC Roots 主要是栈里的<strong>局部变量</strong>、<strong>静态变量</strong>、<strong>常量</strong>、<strong>native 引用</strong>。四种引用从强到弱：<strong>强</strong>（绝不回收）、<strong>软</strong>（内存不够才回收，适合做缓存）、<strong>弱</strong>（一 GC 就回收）、<strong>虚</strong>（拿不到对象，只在回收时收个通知，NIO 清理<strong>直接内存</strong>就靠它）。</p><p><strong>我的项目关联</strong> 我们做<strong>本地缓存</strong>时逻辑上跟「<strong>软引用</strong>/<strong>弱引用</strong>」思路一致：能用 <strong>Redis</strong> 就用 Redis，本地只放短期数据。<strong>ThreadLocal</strong> 的 key 是<strong>弱引用</strong>这个点，在 <strong>Netty</strong> 里很关键——Netty 的 <strong>FastThreadLocal</strong> 就是为了替代 ThreadLocal 的性能和<strong>内存泄漏</strong>问题。这块属于理解原理，没在线上出过事。</p><p><strong>面试答题话术</strong> 「判断垃圾用<strong>可达性分析</strong>，从 <strong>GC Roots</strong> 出发走不到的才算垃圾。<strong>GC Roots</strong> 就是栈里的变量、<strong>静态变量</strong>、<strong>常量</strong>这些。四种引用：<strong>强引用</strong>不回收；<strong>软引用</strong>内存不足时才回收，适合做缓存；<strong>弱引用</strong>一 GC 就没，<strong>ThreadLocal</strong> 的 key 用的就是它；<strong>虚引用</strong>拿不到对象，只用来在回收时收通知，NIO 释放<strong>堆外内存</strong>就是这套。项目里缓存我是直接用 <strong>Redis</strong>，不靠 JVM 软引用，因为 JVM 缓存不好控容量。」</p><hr><h2 id="_4-gc-三大算法-★★★" tabindex="-1">4. GC 三大算法 ★★★ <a class="header-anchor" href="#_4-gc-三大算法-★★★" aria-label="Permalink to &quot;4. GC 三大算法 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>标记清除</strong>：标出活的、清掉死的，简单但有<strong>内存碎片</strong>。<strong>复制</strong>：内存分两半，把活的复制到另一半，没碎片但费空间——不过<strong>新生代</strong>实际是 <strong>Eden</strong> 和两块 <strong>Survivor</strong> <strong>8:1:1</strong>，只浪费 <strong>10%</strong>，而且新生代对象大多<strong>朝生夕死</strong>，复制成本低。<strong>标记整理</strong>：把活对象都挪到一边，没碎片但移动成本高、要 <strong>STW</strong>。所以<strong>新生代用复制、老年代用标记整理</strong>。</p><p><strong>我的项目关联</strong> 这个不用死记，记住「<strong>新生代复制、老年代整理</strong>」的取舍就行。我们服务用 <strong>G1</strong>，<strong>新生代</strong>回收就是把存活对象从 <strong>Eden</strong> 搬到 <strong>Survivor</strong>，日志里看到 Eden 被打满触发 <strong>Young GC</strong> 就是这个过程。</p><p><strong>面试答题话术</strong> 「三个算法：<strong>标记清除</strong>有碎片；<strong>复制</strong>没碎片但要浪费空间，新生代用，因为对象大多<strong>朝生夕死</strong>，复制量小，而且 <strong>8:1:1</strong> 只浪费 <strong>10%</strong>；<strong>标记整理</strong>没碎片但要移动对象、得 <strong>STW</strong>，老年代用。一句话记：<strong>新生代复制，老年代整理</strong>。」</p><hr><h2 id="_5-常见垃圾收集器-重点-g1-★★★-【简历亮点-高频追问】" tabindex="-1">5. 常见垃圾收集器（重点 G1）★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_5-常见垃圾收集器-重点-g1-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;5. 常见垃圾收集器（重点 G1）★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong> 演进路线：<strong>Serial</strong>（单线程，小内存）→ <strong>Parallel</strong>（多线程，追求吞吐，JDK8 默认）→ <strong>CMS</strong>（并发低停顿，但有碎片、有浮动垃圾，已废弃）→ <strong>G1</strong>（把堆切成很多 <strong>Region</strong>，优先回收垃圾最多的，停顿可预测，JDK9 起默认）→ <strong>ZGC</strong>（<strong>着色指针</strong> + <strong>读屏障</strong>，停顿亚毫秒级，支持 TB 级堆）。现在新项目基本 <strong>G1</strong> 起步，大堆低延迟才上 ZGC。</p><p><strong>我的项目关联</strong> 我们 JDK 21，默认就是 <strong>G1</strong>，参数上配了 <code>-XX:MaxGCPauseMillis</code> 控制停顿目标。<strong>G1</strong> 的核心是 <strong>Region</strong>：它不像以前那样物理划分<strong>新生代</strong>老年代，而是把堆切成一堆小块，每次挑垃圾最多的几块回收，这也是名字 <strong>Garbage First</strong> 的由来。对账服务批次跑批时会有对象突增，我们就是靠 G1 的<strong>可预测停顿</strong> + 监控 <strong>GC 日志</strong>来兜。</p><p><strong>面试答题话术</strong> 「现在主流是 <strong>G1</strong>，JDK9 之后默认。它的思路是把堆切成很多大小相等的 <strong>Region</strong>，回收时优先挑垃圾最多的 Region，所以叫 <strong>Garbage First</strong>，还能用 MaxGCPauseMillis 设停顿目标。<strong>CMS</strong> 追求低停顿但用<strong>标记清除</strong>，有碎片、有浮动垃圾，而且并发阶段抢 CPU，JDK9 就废弃了。<strong>ZGC</strong> 是<strong>着色指针</strong>加<strong>读屏障</strong>，大部分工作并发做，<strong>STW</strong> 极短，适合超大堆。我项目里 JDK21 默认 <strong>G1</strong>，主要调停顿目标配合 <strong>GC 日志</strong>看。」</p><hr><h2 id="_6-类加载全过程-双亲委派-★★★" tabindex="-1">6. 类加载全过程；双亲委派 ★★★ <a class="header-anchor" href="#_6-类加载全过程-双亲委派-★★★" aria-label="Permalink to &quot;6. 类加载全过程；双亲委派 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 类加载五步：<strong>加载</strong>（读字节码、生成 Class 对象）→ <strong>验证</strong>（保证字节码安全）→ <strong>准备</strong>（静态变量给零值，比如 <code>static int i = 1</code> 此时 i 还是 0）→ <strong>解析</strong>（符号引用换直接引用）→ <strong>初始化</strong>（执行 <code>&lt;clinit&gt;</code>，真正给静态变量赋值、跑静态代码块）。<strong>双亲委派</strong>就是：要加载一个类，先让父加载器去加载，父的加载不了才自己上。好处是避免重复加载、防止自己写个假的 <code>java.lang.String</code> 把核心类替换掉。破坏它的典型场景是 <strong>JDBC</strong> 的 <strong>SPI</strong> 和 <strong>Tomcat</strong> 的<strong>类隔离</strong>。</p>',20)),(t(),g(e,null,{default:o(()=>[a(n,{id:"mermaid-115",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%E5%8A%A0%E8%BD%BD%3Cbr%2F%3E%E8%AF%BB%E5%AD%97%E8%8A%82%E7%A0%81%E7%94%9F%E6%88%90%20Class%5D%20--%3E%20B%5B%E9%AA%8C%E8%AF%81%3Cbr%2F%3E%E5%AD%97%E8%8A%82%E7%A0%81%E5%AE%89%E5%85%A8%5D%0A%20%20%20%20B%20--%3E%20C%5B%E5%87%86%E5%A4%87%3Cbr%2F%3E%E9%9D%99%E6%80%81%E5%8F%98%E9%87%8F%E8%B5%8B%E9%9B%B6%E5%80%BC%5D%0A%20%20%20%20C%20--%3E%20D%5B%E8%A7%A3%E6%9E%90%3Cbr%2F%3E%E7%AC%A6%E5%8F%B7%E5%BC%95%E7%94%A8%E8%BD%AC%E7%9B%B4%E6%8E%A5%E5%BC%95%E7%94%A8%5D%0A%20%20%20%20D%20--%3E%20E%5B%E5%88%9D%E5%A7%8B%E5%8C%96%3Cbr%2F%3Eclinit%20%E7%9C%9F%E6%AD%A3%E8%B5%8B%E5%80%BC%5D%0A"})]),fallback:o(()=>r[1]||(r[1]=[l(" Loading... ")])),_:1})),(t(),g(e,null,{default:o(()=>[a(n,{id:"mermaid-116",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20A%5B%E5%8A%A0%E8%BD%BD%E7%B1%BB%E8%AF%B7%E6%B1%82%5D%20--%3E%20B%7B%E7%88%B6%E5%8A%A0%E8%BD%BD%E5%99%A8%3Cbr%2F%3E%E8%83%BD%E5%8A%A0%E8%BD%BD%E5%90%97%3F%7D%0A%20%20%20%20B%20--%20%E8%83%BD%20--%3E%20C%5B%E7%88%B6%E5%8A%A0%E8%BD%BD%E5%99%A8%E5%8A%A0%E8%BD%BD%5D%0A%20%20%20%20B%20--%20%E4%B8%8D%E8%83%BD%20--%3E%20D%5B%E8%87%AA%E5%B7%B1%E5%8A%A0%E8%BD%BD%5D%0A"})]),fallback:o(()=>r[2]||(r[2]=[l(" Loading... ")])),_:1})),r[5]||(r[5]=s('<p><strong>我的项目关联</strong> 实际开发不太会自己写<strong>类加载器</strong>，但有两个点面试常问：一是<strong>准备阶段</strong>和<strong>初始化阶段</strong>对静态变量的区别；二是为什么 <strong>JDBC</strong> 驱动能被加载——因为 <code>DriverManager</code> 是<strong>启动类加载器</strong>加载的，加载不到 classpath 里的驱动实现，所以用<strong>线程上下文类加载器</strong>反向去拿。<strong>SPI</strong> 这个我们在对接第三方时就靠这类机制（JDK 的 SPI、Spring 的 <code>SpringFactoriesLoader</code> 都是这个套路）。</p><p><strong>面试答题话术</strong> 「类加载五步：<strong>加载</strong>、<strong>验证</strong>、<strong>准备</strong>、<strong>解析</strong>、<strong>初始化</strong>。<strong>准备阶段</strong>只给静态变量设零值，真正赋值在<strong>初始化阶段</strong>，这是常考的点。<strong>双亲委派</strong>就是向上委托，父加载器加载不了才自己加载，目的是避免重复加载、防止核心类被篡改。破坏它的经典例子是 <strong>JDBC</strong>：DriverManager 由<strong>启动类加载器</strong>加载，但驱动实现类在 classpath 里，所以用<strong>线程上下文类加载器</strong>反向加载，这就是 <strong>SPI</strong> 机制。Spring 里加载自动配置的 <strong>SpringFactoriesLoader</strong> 也是同一个思路。」</p><hr><h2 id="_7-oom-常见场景与排查工具-jmap-jstack-jstat-★★★-【简历亮点-高频追问】" tabindex="-1">7. OOM 常见场景与排查工具（jmap / jstack / jstat）★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_7-oom-常见场景与排查工具-jmap-jstack-jstat-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;7. OOM 常见场景与排查工具（jmap / jstack / jstat）★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong> 常见 OOM：<strong>堆溢出</strong>（对象太多/大对象，<code>Java heap space</code>）、<strong>栈溢出</strong>（递归太深，<code>StackOverflowError</code>）、<strong>元空间溢出</strong>（动态生成类太多，<code>Metaspace</code>）、<strong>GC 开销超限</strong>（<code>GC overhead limit exceeded</code>）、<strong>直接内存溢出</strong>（<code>Direct buffer memory</code>）。工具箱：<strong>jps</strong> 看进程、<strong>jstat</strong> 看 GC、<strong>jmap</strong> 导出堆快照给 <strong>MAT</strong> 分析、<strong>jstack</strong> 打线程栈查死锁和 CPU 高的线程。</p><p><strong>我的项目关联</strong> 我们线上服务开了 <code>-XX:+HeapDumpOnOutOfMemoryError</code>，真 <strong>OOM</strong> 了会自动 <strong>dump</strong>，然后我用 <strong>MAT</strong> 看谁占得最多。查 CPU 飙高是「top 找进程 → <code>top -Hp</code> 找线程 → 线程号转十六进制 → <strong>jstack</strong> 里找 <strong>nid</strong>」这套。这块属于我的运维基本功，配合监控告警用，<strong>说明一下</strong>：我们线上没有发生过严重<strong>堆 OOM</strong>，这个流程是日常排障和演练用的，不是「出过大事才学会」。</p><p><strong>面试答题话术</strong> 「排查思路先说工具：<strong>jps</strong> 找进程、<strong>jstat</strong> 看 GC 频率和堆变化、<strong>jmap</strong> 导堆快照给 <strong>MAT</strong> 找大对象、<strong>jstack</strong> 看线程栈。<strong>堆 OOM</strong> 一般是对象泄漏或者大对象，看 MAT 的<strong>支配树</strong>找谁在占；CPU 飙高是 top 找进程、top -Hp 找线程、线程号转十六进制、再去 jstack 找 nid，一般是死循环、频繁 <strong>Full GC</strong> 或者<strong>锁竞争</strong>。我们生产开了 HeapDumpOnOutOfMemoryError，真出事能留现场，平时靠监控先发现 GC 异常。」</p><hr><h2 id="_8-逃逸分析、栈上分配-★★☆" tabindex="-1">8. 逃逸分析、栈上分配 ★★☆ <a class="header-anchor" href="#_8-逃逸分析、栈上分配-★★☆" aria-label="Permalink to &quot;8. 逃逸分析、栈上分配 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><strong>逃逸分析</strong>：<strong>JIT</strong> 判断一个对象会不会「跑出」方法或线程。不会跑出去的，就能做优化——<strong>栈上分配</strong>（对象随方法结束直接销毁，不进堆）、<strong>标量替换</strong>（把对象拆成基本类型）、<strong>锁消除</strong>（不会被别人共享就把 <strong>synchronized</strong> 去掉）。HotSpot 默认开，但真正生效的是<strong>标量替换</strong>，不是字面意义的栈上分配。</p><p><strong>我的项目关联</strong> 记结论就行，实践中影响很小，属于面试凑分点。真正跟性能相关的是「<strong>锁消除</strong>」，比如方法里 new 一个 <strong>StringBuilder</strong> 加 <strong>synchronized</strong>，<strong>逃逸分析</strong>会直接把锁干掉。</p><p><strong>面试答题话术</strong> 「<strong>逃逸分析</strong>是 <strong>JIT</strong> 判断对象会不会逃出方法。不逃逸的可以做<strong>栈上分配</strong>、<strong>标量替换</strong>、<strong>锁消除</strong>。默认是开的，但其实 HotSpot 没有真正的栈上分配，是靠<strong>标量替换</strong>实现的。这个点实际价值不大，知道结论就行。」</p><hr><h2 id="_9-jvm-常用调优参数-★★☆" tabindex="-1">9. JVM 常用调优参数 ★★☆ <a class="header-anchor" href="#_9-jvm-常用调优参数-★★☆" aria-label="Permalink to &quot;9. JVM 常用调优参数 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 堆：<code>-Xms</code>/<code>-Xmx</code>（建议设成相等，避免动态扩容抖动）、<code>-Xmn</code> <strong>新生代</strong>；栈：<code>-Xss</code>；<strong>元空间</strong>：<code>-XX:MaxMetaspaceSize</code>；选 GC：<code>-XX:+UseG1GC</code>；停顿目标：<code>-XX:MaxGCPauseMillis</code>；日志：<code>-Xlog:gc*</code>；OOM 自动 dump：<code>-XX:+HeapDumpOnOutOfMemoryError</code>。思路是「<strong>先看监控再调</strong>」，别上来就加内存。</p><p><strong>我的项目关联</strong> 我们的服务打包成 <strong>Docker</strong> 镜像，<strong>JVM 参数</strong>统一写在启动脚本/编排里：堆固定大小、<strong>元空间</strong>上限、开 <strong>GC 日志</strong>、开 <strong>OOM dump</strong>。核心理念是容器内存就那么多，<strong>JVM 参数</strong>必须显式给，不能靠默认值——容器里 JVM 识别不到宿主内存，默认值可能超容器限额被 <strong>OOM Killer</strong> 干掉。</p><p><strong>面试答题话术</strong> 「参数就几类：堆用 <strong>Xms/Xmx</strong>，一般设成相等避免<strong>扩容抖动</strong>；栈用 <strong>Xss</strong>；<strong>元空间</strong>设 <strong>MaxMetaspaceSize</strong>；GC 用 <strong>UseG1GC</strong>；停顿目标用 <strong>MaxGCPauseMillis</strong>；再开 <strong>GC 日志</strong>和 <strong>OOM dump</strong>。调优思路是<strong>先看监控和 GC 日志</strong>，确认是内存、CPU 还是 GC 瓶颈再动手。放到容器里有个坑：JVM 默认堆是按宿主内存算的，容器里不显式设可能超限额被系统杀掉。」</p><hr><h2 id="_10-jmm-与-jvm-内存模型的区别-★★★" tabindex="-1">10. JMM 与 JVM 内存模型的区别 ★★★ <a class="header-anchor" href="#_10-jmm-与-jvm-内存模型的区别-★★★" aria-label="Permalink to &quot;10. JMM 与 JVM 内存模型的区别 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 这是两个完全不同的东西，最容易被混淆。<strong>JVM 内存模型</strong>（运行时数据区）说的是「数据存在哪」——堆、栈、方法区。<strong>JMM</strong>（Java 内存模型）说的是「多线程怎么安全读写共享变量」——把内存抽象成<strong>主内存</strong>（共享）和每个线程的<strong>工作内存</strong>（私有副本），通过 <strong>volatile</strong>、<strong>synchronized</strong>、<strong>final</strong> 这些建立 <strong>happens-before</strong> 规则，保证<strong>可见性</strong>和<strong>有序性</strong>。</p><p><strong>我的项目关联</strong> 网关是多线程环境，<strong>Netty</strong> Worker 线程和 <strong>Kafka</strong> 消费线程都在跑，共享状态（设备会话、下发队列标志位）都必须用 <strong>volatile</strong> 或者<strong>原子类</strong>。我们踩过（通用坑级别）：一个「<strong>停止标志</strong>」没用 volatile，改了之后线程读的还是旧值，循环停不下来——这是 <strong>JMM 可见性</strong>的经典问题，解决办法就是加 volatile 或者用 <strong>AtomicBoolean</strong>。</p><p><strong>面试答题话术</strong> 「这两个别混：<strong>JVM 内存模型</strong>说的是数据放在哪，是堆栈方法区，是存储划分；<strong>JMM</strong> 是并发规范，说的是<strong>主内存</strong>和<strong>工作内存</strong>，解决多线程读写共享变量的<strong>可见性</strong>和<strong>有序性</strong>。<strong>JMM</strong> 靠 <strong>volatile</strong>、<strong>synchronized</strong>、<strong>happens-before</strong> 来立规矩。我项目里网关是多线程的，共享的开关标志一定用 <strong>volatile</strong> 或 <strong>AtomicBoolean</strong>，不然改了别的线程读不到。」</p><hr><h2 id="_11-元空间-vs-永久代、字符串常量池位置-★★☆" tabindex="-1">11. 元空间 vs 永久代、字符串常量池位置 ★★☆ <a class="header-anchor" href="#_11-元空间-vs-永久代、字符串常量池位置-★★☆" aria-label="Permalink to &quot;11. 元空间 vs 永久代、字符串常量池位置 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> JDK8 之前方法区的实现叫<strong>永久代</strong>（在堆里，受 <code>-XX:MaxPermSize</code> 限制）；JDK8 之后换成<strong>元空间</strong>，挪到<strong>本地内存</strong>，默认没上限，得用 <code>-XX:MaxMetaspaceSize</code> 自己限。<strong>字符串常量池</strong> JDK7 就从永久代挪到堆里了。本质是避免固定大小导致<strong>永久代 OOM</strong>。</p><p><strong>我的项目关联</strong> 不用深挖，记住「8 之后是<strong>元空间</strong>、在<strong>本地内存</strong>、要自己设上限」就够了。我们用 <strong>CGLIB</strong> 做代理的场景不少，<strong>代理类</strong>都会进<strong>元空间</strong>，所以启动参数固定给 <strong>MaxMetaspaceSize</strong>。</p><p><strong>面试答题话术</strong> 「8 之前是<strong>永久代</strong>，在堆里、有固定大小、容易 <strong>OOM</strong>；8 之后是<strong>元空间</strong>，挪到<strong>本地内存</strong>，默认没上限，得用 <strong>MaxMetaspaceSize</strong> 限。<strong>字符串常量池</strong> 7 就移到堆里了。一句话：<strong>元空间就是方法区的新实现</strong>，但换了物理位置。」</p><hr><h2 id="_12-直接内存-netty-重点-★★☆" tabindex="-1">12. 直接内存（Netty 重点）★★☆ <a class="header-anchor" href="#_12-直接内存-netty-重点-★★☆" aria-label="Permalink to &quot;12. 直接内存（Netty 重点）★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><strong>NIO</strong> 的 <code>ByteBuffer.allocateDirect</code> 分配的是<strong>堆外内存</strong>，好处是不受 GC 管、省掉了堆内堆外拷贝，做网络 IO 性能好。代价是不在堆里、不好监控，满了抛 <code>Direct buffer memory</code>，要手动设 <code>-XX:MaxDirectMemorySize</code>。释放靠<strong>虚引用</strong> + <strong>Cleaner</strong>，等 GC 时回收。</p><p><strong>我的项目关联</strong><strong>这块跟我们网关强相关，要能讲。</strong> <strong>Netty</strong> 默认就用<strong>堆外直接内存</strong>（<code>PooledByteBufAllocator</code>）收发充电桩报文，性能好。风险也很直接：如果<strong>直接内存</strong>设得太小或者 <strong>ByteBuf</strong> 没释放，就会报 <code>Direct buffer memory</code> <strong>OOM</strong>，而且<strong>堆 dump</strong> 里看不到——因为它在堆外。所以我们的经验是：<code>-XX:MaxDirectMemorySize</code> 显式给足，Netty 的 ByteBuf 严格按<strong>引用计数</strong> release，用 Netty 自带的<strong>内存泄漏检测</strong>（<code>-Dio.netty.leakDetection.level</code>）在测试环境先照出来。</p><p><strong>面试答题话术</strong> 「<strong>直接内存</strong>是<strong>堆外内存</strong>，<strong>NIO</strong> 用它是因为省掉一次堆内堆外拷贝，IO 性能好，<strong>Netty</strong> 默认就用这个。坑是它在堆外，<strong>GC 日志</strong>和<strong>堆 dump</strong> 都看不到，满了报 Direct buffer memory，而且默认上限等于 Xmx，容器里要显式设 <strong>MaxDirectMemorySize</strong>。释放靠 <strong>Cleaner</strong> 加<strong>虚引用</strong>，得等 GC。我们网关用 Netty，所以对 <strong>ByteBuf</strong> 的 release 和 Netty 自带的<strong>内存泄漏检测</strong>看得比较重。」</p><hr><h2 id="_13-三色标记、对象进老年代条件、stw-★★☆" tabindex="-1">13. 三色标记、对象进老年代条件、STW ★★☆ <a class="header-anchor" href="#_13-三色标记、对象进老年代条件、stw-★★☆" aria-label="Permalink to &quot;13. 三色标记、对象进老年代条件、STW ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><strong>三色标记</strong>是<strong>并发标记</strong>用的：<strong>白</strong>（没扫到）、<strong>灰</strong>（扫到了但子对象没扫完）、<strong>黑</strong>（子对象都扫完）。并发时用户线程还在改引用，容易「<strong>漏标</strong>」，所以 <strong>CMS</strong> 用<strong>增量更新</strong>、<strong>G1</strong> 用 <strong>SATB</strong>（原始快照）来补救。对象进老年代：年龄到阈值（默认 <strong>15</strong>）、<strong>大对象</strong>直接进、<strong>Survivor</strong> 塞不下触发<strong>动态年龄判断</strong>。<strong>STW</strong> 就是 GC 时停掉所有用户线程，任何 GC 都有 STW，只是长短不同。</p><p><strong>我的项目关联</strong> 结论够用。<strong>G1</strong> 的 <strong>SATB</strong> 我答一句就行：靠<strong>写屏障</strong>记录并发期间的引用变化，最后重新扫一遍这些，防止对象被误回收。这块属于知道结论，没在项目里深调。</p><p><strong>面试答题话术</strong> 「<strong>三色标记</strong>就是<strong>白灰黑</strong>三种状态，<strong>并发标记</strong>时会<strong>漏标</strong>，所以 <strong>CMS</strong> 用<strong>增量更新</strong>、<strong>G1</strong> 用 <strong>SATB</strong> 补救。对象进老年代主要看年龄到 <strong>15</strong>、<strong>大对象</strong>直接进、<strong>Survivor</strong> 放不下动态晋升。<strong>STW</strong> 是所有 GC 都有的，只是 <strong>ZGC</strong> 那种能压到极短，所谓低停顿就是压 <strong>STW</strong> 时间。」</p><hr><h2 id="_14-jvm-出现-oom-会导致进程挂掉吗-★★★" tabindex="-1">14. JVM 出现 OOM 会导致进程挂掉吗 ★★★ <a class="header-anchor" href="#_14-jvm-出现-oom-会导致进程挂掉吗-★★★" aria-label="Permalink to &quot;14. JVM 出现 OOM 会导致进程挂掉吗 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 不一定，看 <strong>OOM</strong> 出在哪、有没有被捕获。<strong>堆 OOM</strong> 抛 <code>OutOfMemoryError</code>，如果没人 catch，通常只是当前那个线程挂了，JVM 本身可能还活着（但也不健康）。<strong>元空间</strong>、栈、<strong>直接内存 OOM</strong> 同理，都是抛异常。真正让进程「直接消失」的是操作系统层面的 <strong>OOM Killer</strong>，进程被 kill 掉，日志里没有 Java 异常。注意 <code>OutOfMemoryError</code> 是 <code>Throwable</code>，<code>catch(Throwable)</code> 能抓到，但抓完进程状态通常已经不可靠了。</p><p><strong>我的项目关联</strong> 实际经验是：<strong>OOM</strong> 后即使进程没死也建议尽快重启，因为内存状态已经乱了，容易<strong>连环 OOM</strong>。容器里更要注意——如果 <strong>JVM 堆</strong>超过了容器的 <strong>memory limit</strong>，是直接被 <strong>OOM Killer</strong> 杀掉，<strong>pod</strong> 直接重启，这时候要去看 <strong>dmesg</strong> 或者容器的 <strong>exit code 137</strong>，而不是 Java 日志。这个坑我们是通过给 JVM 显式设堆上限 + 容器 limit 留富余来防的。</p><p><strong>面试答题话术</strong> 「不一定。<strong>堆 OOM</strong>、<strong>元空间 OOM</strong> 都是抛 <strong>OutOfMemoryError</strong>，如果没人 catch，一般是当前线程挂，进程可能还活着，但已经不可靠了，建议尽快重启。进程直接消失一般是操作系统 <strong>OOM Killer</strong> 干的，日志里看不到 Java 异常，容器里就要看 <strong>exit code 137</strong>。所以容器部署时 <strong>JVM 堆</strong>要显式设，还得比容器 limit 小一截，给<strong>堆外内存</strong>留空间。」</p><hr><h2 id="_15-堆和栈的区别-★★★" tabindex="-1">15. 堆和栈的区别 ★★★ <a class="header-anchor" href="#_15-堆和栈的区别-★★★" aria-label="Permalink to &quot;15. 堆和栈的区别 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>堆</strong>和<strong>栈</strong>是 JVM 里两块最重要的内存，性质完全不同。<strong>栈是线程私有的</strong>，每个线程一份，存的是「方法的执行过程」——一个个<strong>栈帧</strong>（<strong>局部变量表</strong>、<strong>操作数栈</strong>、<strong>动态链接</strong>、<strong>返回地址</strong>），方法调用就压栈、方法返回就弹栈，用完即走、不需要 <strong>GC</strong>，但容量小（默认 1MB 左右），递归太深就 <strong>StackOverflowError</strong>。<strong>堆是线程共享的</strong>，存的是「对象实例」——new 出来的东西全在这，容量大（几百 M 到几十 G），是 <strong>GC 的主战场</strong>。一句话：<strong>栈管「方法怎么跑」，堆管「对象放哪」</strong>。</p><p><strong>我的项目关联</strong> 网关里这个区分很直观：<strong>Netty</strong> 每个连接都有 handler，一次报文解析的临时字节数组、解析结果这些<strong>局部变量</strong>都在<strong>栈</strong>上，方法结束就没了；而设备的会话状态、下发队列这些对象都在<strong>堆</strong>上，是长期存活、要交给 <strong>GC</strong> 管的。调优也体现这个区别：栈一般不用动（默认 <strong>Xss</strong> 够用，除非递归很深），我们主要调的是堆（<strong>Xms/Xmx</strong>）和堆上的 <strong>GC 行为</strong>。</p><p><strong>面试答题话术</strong> 「<strong>堆和栈</strong>是两个维度。<strong>栈是线程私有的</strong>，每个方法一个<strong>栈帧</strong>，存<strong>局部变量</strong>和调用信息，用完就弹栈，不用 GC，但容量小，递归深了就是 <strong>StackOverflowError</strong>。<strong>堆是线程共享的</strong>，存<strong>对象实例</strong>，是 <strong>GC 主要工作的地方</strong>，容量大。还可以补一句常说的：<strong>对象的引用在栈里，对象本体在堆里</strong>。我项目里基本不动栈参数，主要调堆的大小和 GC 参数。」</p><hr><h2 id="_16-jvm-的即时编译器-jit-如何工作、热点代码与分层编译-★★☆" tabindex="-1">16. JVM 的即时编译器（JIT）如何工作、热点代码与分层编译 ★★☆ <a class="header-anchor" href="#_16-jvm-的即时编译器-jit-如何工作、热点代码与分层编译-★★☆" aria-label="Permalink to &quot;16. JVM 的即时编译器（JIT）如何工作、热点代码与分层编译 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> Java 是「先解释、后编译」：启动时<strong>字节码</strong>先被<strong>解释器</strong>逐条执行，等某些代码执行频率上来了，<strong>JIT</strong>（Just-In-Time）就把这些「<strong>热点代码</strong>」编译成<strong>本地机器码</strong>，之后直接跑机器码，速度大幅提升。判断热点靠两个计数器：<strong>方法调用计数器</strong>（方法被调用的次数）和<strong>回边计数器</strong>（循环体执行的次数），超过阈值就触发编译。<strong>分层编译</strong>（JDK8 后默认开启）就是分阶段递进：第 0 层纯解释 → 第 1~3 层 <strong>C1 编译</strong>（编译快、优化少）→ 第 4 层 <strong>C2 编译</strong>（编译慢、优化激进）。这样既保证启动快，又保证跑到后面性能好。</p><p><strong>我的项目关联</strong> 对账服务有典型的<strong>跑批场景</strong>：批量对账任务一跑就是几十分钟，前几分钟慢、后来越来越快，就是 <strong>JIT</strong> 把<strong>热点方法</strong>（对账明细比对逻辑、金额计算）编译成机器码了。理解这点就知道「<strong>预热</strong>」很重要——压测和线上刚重启后的前几分钟延迟偏高是正常现象，别急着调参数。生产上 JDK 21 默认<strong>分层编译</strong>就够用，我们没专门去调 <strong>C1/C2</strong>，属于理解原理即可。（这是「<strong>通用坑</strong>」，不是线上事故，面试时别说成自己踩过。）</p><p><strong>面试答题话术</strong> 「<strong>JIT</strong> 就是把执行频繁的<strong>热点代码</strong>编译成本地机器码，替换掉解释执行，所以 Java 有『<strong>越跑越快</strong>』的特点。热点判断靠两个计数器：<strong>方法调用计数器</strong>和<strong>回边计数器</strong>，超过阈值才编译。<strong>分层编译</strong>就是分阶段：先纯解释，再用 <strong>C1</strong> 做快但优化少的编译，最后用 <strong>C2</strong> 做慢但优化激进的编译，兼顾启动速度和峰值性能。我项目里对账跑批就有这个现象，刚启动慢、越跑越快，就是 JIT 在起作用。」</p><hr><h2 id="_17-什么是内存屏障-jvm-如何使用它保证可见性与有序性-★★★" tabindex="-1">17. 什么是内存屏障，JVM 如何使用它保证可见性与有序性 ★★★ <a class="header-anchor" href="#_17-什么是内存屏障-jvm-如何使用它保证可见性与有序性-★★★" aria-label="Permalink to &quot;17. 什么是内存屏障，JVM 如何使用它保证可见性与有序性 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>内存屏障</strong>是 CPU 层面的一类指令，作用是「挡墙」：规定屏障两边的内存操作不能乱序、不能让多核之间的缓存乱同步。分两大类：<strong>读屏障</strong>（Load Barrier，屏障后的读不能重排到屏障前）和<strong>写屏障</strong>（Store Barrier，屏障前的写不能重排到屏障后），组合起来有四种：<strong>LoadLoad</strong> / <strong>StoreStore</strong> / <strong>LoadStore</strong> / <strong>StoreLoad</strong>，其中 <strong>StoreLoad</strong> 最强、代价也最高，几乎什么重排都挡。JVM 编译 <strong>volatile</strong> 写的时候会在后面插 StoreLoad 屏障：把<strong>工作内存</strong>的写刷回<strong>主内存</strong>，同时让其他核的缓存失效，这就保证了<strong>可见性</strong>；再靠「<strong>禁止指令重排</strong>」保证<strong>有序性</strong>。换句话说，<strong>happens-before</strong> 规则在硬件上就是靠这些屏障落地的。</p><p><strong>我的项目关联</strong> 网关里共享状态必须用 <strong>volatile</strong>（比如「是否已下发指令」的开关位），它的正确性本质就是靠<strong>内存屏障</strong>保证的——不插屏障，CPU 和 <strong>JIT</strong> 都可能把读写重排，别的线程就看不到最新值。我答这个题会落到一句话：<strong>volatile 的可见性和有序性，本质就是编译器在读写前后插了内存屏障</strong>。这块属于理解原理，JVM 自动插屏障，开发者不用手写，所以没在线上单独调过。</p><p><strong>面试答题话术</strong> 「<strong>内存屏障</strong>是 CPU 指令，作用是禁止屏障两边的操作重排，并保证多核之间的<strong>缓存一致性</strong>。它分<strong>读屏障</strong>和<strong>写屏障</strong>，组合起来四种，其中 <strong>StoreLoad</strong> 最强、代价最高。JVM 用它来落地 <strong>volatile</strong> 和 <strong>happens-before</strong>：写 volatile 时在后面插 StoreLoad 屏障，把写刷回<strong>主内存</strong>、让其他核缓存失效，这就是<strong>可见性</strong>；同时屏障禁止重排，这就是<strong>有序性</strong>。一句话：<strong>volatile 的语义就是靠内存屏障硬撑起来的</strong>。」</p><hr><h2 id="_18-如何排查和解决-jvm-内存泄漏问题-★★★" tabindex="-1">18. 如何排查和解决 JVM 内存泄漏问题 ★★★ <a class="header-anchor" href="#_18-如何排查和解决-jvm-内存泄漏问题-★★★" aria-label="Permalink to &quot;18. 如何排查和解决 JVM 内存泄漏问题 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>内存泄漏</strong>就是「对象已经没用了，但还被引用着，<strong>GC 回收不掉</strong>」，于是堆慢慢涨，最后 <strong>OOM</strong>。排查思路：先确认是不是真泄漏——看 <strong>GC 日志</strong>，<strong>老年代</strong>只涨不降、<strong>Full GC</strong> 之后还回不去，那就是泄漏；再用 <strong>jmap</strong> 导 <strong>heap dump</strong>（或靠 <code>-XX:+HeapDumpOnOutOfMemoryError</code> 自动导），用 <strong>MAT</strong> 打开，看「<strong>支配树</strong>」「<strong>Histogram</strong>」找占内存最大的对象，然后顺着 <strong>GC Roots 引用链</strong>找到「是谁在一直持有它不放」。常见泄漏源：<strong>static 集合</strong>一直 add 不 remove、<strong>ThreadLocal</strong> 用完不 remove（尤其<strong>线程池</strong>复用线程）、<strong>监听器/回调</strong>注册了不注销、流和连接不关闭、<strong>缓存没上限</strong>。</p><p><strong>我的项目关联</strong> 我们生产开了 <code>-XX:+HeapDumpOnOutOfMemoryError</code>，真有情况能留现场。排查套路是：<strong>MAT</strong> 打开 <strong>dump</strong> → 看 <strong>Histogram</strong> 里谁的实例数/占用最大 → 点开它的 <strong>GC Roots</strong> → 找到引用它的那条链，定位到代码里「忘了 remove / 忘了释放」的地方。最常见的坑（<strong>通用坑</strong>级别，我们没真踩到）：<strong>ThreadLocal</strong> 没 remove——因为<strong>线程池</strong>线程复用，ThreadLocal 里存的东西会跨请求一直挂着；还有<strong>静态 Map</strong> 当缓存用、key 一直增加。修复就是加 remove、加容量上限或换成 <strong>LRU</strong>。（这几种是资料里学到的，面试时如实说是通用坑。）</p><p><strong>面试答题话术</strong> 「先判断是不是真泄漏：看 <strong>GC 日志</strong>，<strong>老年代</strong>在 <strong>Full GC</strong> 之后还持续涨、回不去，就是泄漏。然后 <strong>jmap</strong> 导 <strong>dump</strong>，用 <strong>MAT</strong> 看<strong>支配树</strong>和 <strong>Histogram</strong>，找出占内存最大的对象，再顺着 <strong>GC Roots 引用链</strong>找到是谁在持有它。常见泄漏源：<strong>static 集合</strong>只增不减、<strong>ThreadLocal</strong> 用完不 remove、<strong>监听器</strong>注册不注销、流和连接不关、<strong>无界缓存</strong>。我项目里是靠 HeapDumpOnOutOfMemoryError 留现场，再用 MAT 定位引用链；ThreadLocal 那个坑是<strong>线程池</strong>复用线程导致的，用完必须 remove。」</p><hr><h2 id="_19-虚拟机栈和本地方法栈的区别与作用-★★☆" tabindex="-1">19. 虚拟机栈和本地方法栈的区别与作用 ★★☆ <a class="header-anchor" href="#_19-虚拟机栈和本地方法栈的区别与作用-★★☆" aria-label="Permalink to &quot;19. 虚拟机栈和本地方法栈的区别与作用 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 两个都是<strong>线程私有</strong>的栈，都是「方法调用用<strong>栈帧</strong>」的结构，区别只在于「跑的是哪种方法」：<strong>虚拟机栈</strong>跑 Java 方法（字节码方法），<strong>本地方法栈</strong>跑 <strong>native 方法</strong>（C/C++ 写的，比如 <code>Object.hashCode</code>、<code>System.arraycopy</code>、NIO 底层实现）。<strong>HotSpot</strong> 里这两块是合在一起的、不分开，所以调优就一个 <code>-Xss</code>。栈帧里四块：<strong>局部变量表</strong>（存参数和局部变量）、<strong>操作数栈</strong>（做运算）、<strong>动态链接</strong>（指向<strong>运行时常量池</strong>的方法引用）、<strong>返回地址</strong>。栈太深（递归）会 <strong>StackOverflowError</strong>，栈空间不够创建新线程会 <strong>OOM</strong>（unable to create native thread）。</p><p><strong>我的项目关联</strong> 记结论即可。真正会遇到的是「<strong>栈相关异常</strong>」：递归写岔了会 <strong>StackOverflowError</strong>；<strong>线程池</strong>开太多线程，每个线程都要一块栈，内存不够就报 <strong>unable to create native thread</strong>。所以线程不是越多越好，网关里线程数都是按核数和 IO 特性算的（<strong>Netty</strong> 默认 2 倍核数），不会乱开。这块没在线上出过大事，属于基础概念。</p><p><strong>面试答题话术</strong> 「<strong>虚拟机栈</strong>是跑 Java 方法的，<strong>本地方法栈</strong>是跑 <strong>native 方法</strong>的，都是<strong>线程私有</strong>、都用<strong>栈帧</strong>，栈帧里有<strong>局部变量表</strong>、<strong>操作数栈</strong>、<strong>动态链接</strong>、<strong>返回地址</strong>。<strong>HotSpot</strong> 把两者合并了，统一用 <strong>Xss</strong> 控制。栈相关异常就两种：递归太深是 <strong>StackOverflowError</strong>，线程开太多导致栈分配不出来是 <strong>OOM</strong>（unable to create native thread）。所以线程数要按核数和业务算，不是越多越好。」</p><hr><h2 id="_20-什么是-jvm-的内存碎片-哪些垃圾收集器会产生-避免碎片-★★☆" tabindex="-1">20. 什么是 JVM 的内存碎片，哪些垃圾收集器会产生/避免碎片 ★★☆ <a class="header-anchor" href="#_20-什么是-jvm-的内存碎片-哪些垃圾收集器会产生-避免碎片-★★☆" aria-label="Permalink to &quot;20. 什么是 JVM 的内存碎片，哪些垃圾收集器会产生/避免碎片 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><strong>内存碎片</strong>就是「堆里东一块西一块的空闲小洞，合起来够用，但没有一块连续的够放一个新对象」。根源是<strong>标记清除算法</strong>：只清死对象、不移动活对象，清完就留下碎片。<strong>CMS</strong> 用标记清除，所以有碎片问题，碎片多了会触发「<strong>并发模式失败</strong>」提前 <strong>Full GC</strong>，甚至退化到 <strong>Serial</strong> 单线程去整理。避免碎片靠「<strong>移动对象、压缩整理</strong>」：<strong>标记整理算法</strong>（<strong>Parallel</strong> 老年代、Serial 老年代）和<strong>复制算法</strong>（新生代各收集器）都不产生碎片；<strong>G1</strong> 是「按 <strong>Region</strong> 复制/整理」，回收时把存活对象挪到别的 Region，也不留碎片。</p><p><strong>我的项目关联</strong> 结论一句话：<strong>CMS 有碎片、G1 没有</strong>。我们 JDK 21 默认 <strong>G1</strong>，靠 <strong>Region</strong> 的复制/整理天然避免碎片，线上不需要担心老年代碎片问题。这个知识主要是为了回答「为什么从 CMS 换到 G1」这类对比题：<strong>CMS</strong> 追求低停顿但用了<strong>标记清除</strong>，长期跑碎片会积累，最后要 <strong>Full GC</strong>、甚至退化到 <strong>Serial</strong> 收拾；<strong>G1</strong> 用复制整理，没这个烦恼。属于理解结论，没在线上调过。</p><p><strong>面试答题话术</strong> 「碎片就是堆里都是小空洞，凑起来够用但放不下一个连续对象。根源是<strong>标记清除</strong>只清不整理，<strong>CMS</strong> 用的就是它，碎片多了会提前触发 <strong>Full GC</strong>，甚至退化到 <strong>Serial</strong> 来整理。避免碎片要靠移动对象：<strong>标记整理</strong>和<strong>复制算法</strong>都不产生碎片。新生代全用复制，天然没碎片；<strong>G1</strong> 按 <strong>Region</strong> 做复制整理，也不留碎片；只有 CMS 因为标记清除有这个坑。我项目 JDK21 默认 G1，没碎片烦恼，这个点主要是为了讲清楚为什么弃用 CMS。」</p><hr><h2 id="_21-jvm-如何处理异常-try-catch-finally-的字节码实现-★★★" tabindex="-1">21. JVM 如何处理异常，try-catch-finally 的字节码实现 ★★★ <a class="header-anchor" href="#_21-jvm-如何处理异常-try-catch-finally-的字节码实现-★★★" aria-label="Permalink to &quot;21. JVM 如何处理异常，try-catch-finally 的字节码实现 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> JVM 处理异常靠的是「<strong>异常表</strong>」：每个方法的 Code 属性里带一张 <strong>exception table</strong>，记录每段<strong>字节码</strong>的范围（from/to）和对应的 <strong>handler</strong>，还有 catch 的异常类型（catch_type）。执行到某条指令抛异常时，JVM 拿着当前 <strong>pc</strong> 去这张表里找能匹配的范围和类型，找到就跳到 handler 执行；找不到就弹掉当前<strong>栈帧</strong>，把异常往上一个调用者抛。<strong>finally</strong> 的实现很特别：<strong>javac</strong> 会把 finally 里的代码<strong>复制到每个分支末尾</strong>（正常路径、每个 catch 路径、甚至没匹配上的异常路径都要各复制一份），所以 finally 一定能执行——不是靠特殊机制，而是靠<strong>代码复制</strong>。这也解释了为什么 finally 里 return 会覆盖前面 try 里的 return。</p><p><strong>我的项目关联</strong> 这个原理在项目里最实用的落地有两点：一是「<strong>finally 里 return 会吞掉异常/覆盖返回值</strong>」——团队约定 finally 里不做 return、不做可能抛异常的操作，否则会掩盖真实问题；二是 <strong>try-with-resources</strong>（JDK7+）本质就是编译器帮我们生成 finally 来 close 资源，<strong>字节码</strong>层面就是 finally 的复制。网关里 <strong>Netty</strong> 的 <strong>ByteBuf</strong> 释放要求严格，我们用 try-with-resources 或手动 finally release，不靠 GC 兜底。（finally 里 return 吞异常这个属于「<strong>通用坑</strong>」，面试时别说成自己踩过。）</p><p><strong>面试答题话术</strong> 「JVM 靠<strong>异常表</strong>处理异常，每个方法的<strong>字节码</strong>里带一张 <strong>exception table</strong>，记录指令范围和对应的 catch <strong>handler</strong>。执行抛异常时，JVM 用当前 <strong>pc</strong> 查表，匹配就跳过去，匹配不到就弹<strong>栈帧</strong>往上抛。<strong>finally</strong> 是编译期把代码复制到每个出口，正常路径、每个 catch、异常路径都复制一份，所以 finally 一定执行，这也解释了 finally 里 return 会覆盖 try 的 return。JDK7 的 <strong>try-with-resources</strong> 本质就是编译器自动生成 finally 去关资源。我项目里约定 finally 不写 return，避免吞异常。」</p><hr><h2 id="_22-jvm-是什么-为什么需要-jvm-跨平台原理-★★★" tabindex="-1">22. JVM 是什么，为什么需要 JVM（跨平台原理）★★★ <a class="header-anchor" href="#_22-jvm-是什么-为什么需要-jvm-跨平台原理-★★★" aria-label="Permalink to &quot;22. JVM 是什么，为什么需要 JVM（跨平台原理）★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>JVM</strong> 是 Java 虚拟机的简称，是一台「用软件模拟出来的计算机」，它运行的是<strong>字节码</strong>，而不是物理 CPU 的机器码。流程是：Java 源码 → <strong>javac</strong> 编译成 .class 字节码 → JVM 加载并执行字节码（解释 + <strong>JIT</strong> 编译成机器码跑）。<strong>跨平台</strong>原理就是「<strong>一次编译，到处运行</strong>」：同一份字节码，在不同操作系统上由各自平台的 JVM 去执行，JVM 把平台差异隔离掉了。代价是比直接编译成机器码的语言（C/C++）多一层，有性能损耗，但 JIT 已经把这个损耗压得很低。附带好处：JVM 还提供<strong>自动内存管理</strong>（GC）、<strong>运行时安全检查</strong>（<strong>字节码验证</strong>、越界检查），所以 Java 更安全。</p><p><strong>我的项目关联</strong> 我们整套微服务都是 Java 的，<strong>跨平台</strong>在部署上直接受益：本地 Windows 开发、<strong>CI</strong> 构建出同一份 jar，扔进 Linux 的 <strong>Docker 镜像</strong>就能跑，不用改代码、不用重编译。<strong>JVM</strong> 的另一个价值是统一的<strong>运行时行为</strong>——<strong>内存模型</strong>、GC、线程语义在不同 OS 上一致，这让网关、对账这些对并发和内存敏感的服务行为可预期，排障经验可以跨环境复用。所以「为什么要 JVM」我答两点：<strong>跨平台 + 统一的内存/并发模型 + 自动 GC</strong>。</p><p><strong>面试答题话术</strong> 「<strong>JVM</strong> 是软件模拟的计算机，执行的是<strong>字节码</strong>。Java 先被 <strong>javac</strong> 编译成字节码，字节码跟平台无关，到各个操作系统上由对应的 JVM 去解释加 <strong>JIT</strong> 执行，这就是<strong>一次编译到处运行</strong>。代价是多一层、有性能损耗，但 JIT 编译成本地机器码后损耗已经很小。附带还有<strong>自动内存管理</strong>和<strong>运行时安全检查</strong>，所以更安全。我项目里感受很深：本地 Windows 写代码，构建出同一份 jar 进 Linux <strong>Docker 镜像</strong>直接跑，不用改任何东西，这就是 JVM <strong>跨平台</strong>的实际收益。」</p><hr><h2 id="附-一句话速记-可以跳过-★☆☆" tabindex="-1">附：一句话速记（可以跳过 ★☆☆） <a class="header-anchor" href="#附-一句话速记-可以跳过-★☆☆" aria-label="Permalink to &quot;附：一句话速记（可以跳过 ★☆☆）&quot;">​</a></h2><ul><li><strong>Serial / ParNew / Parallel</strong>：老收集器，新项目基本不用了，知道名字和特点即可。</li><li><strong>PermGen</strong>：JDK7 及以前的方法区实现，已废弃，现在一律说<strong>元空间</strong>。</li></ul>',85))])}const O=i(p,[["render",h]]);export{J as __pageData,O as default};
